def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    environment = observation.get("environment_name", "resource_collection")
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)

    def get_targets(targets):
        if not targets:
            return []
        return targets

    def move_towards(target):
        dx, dy = 0, 0
        if target:
            dx = 1 if target[0] > sx else -1 if target[0] < sx else 0
            dy = 1 if target[1] > sy else -1 if target[1] < sy else 0
        return dx, dy

    # For pursuit-evasion environment
    if environment == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target_pos = (ox, oy)
            dx, dy = move_towards(target_pos)
            return [dx, dy]
        # Evader: move towards a corner farthest from opponent
        corners = [
            (0, 0),
            (0, grid_height - 1),
            (grid_width - 1, 0),
            (grid_width - 1, grid_height - 1),
        ]
        def dist(corner):
            return abs(corner[0] - ox) + abs(corner[1] - oy)
        target = min(corners, key=dist)
        return move_towards(target)

    # For territory control
    elif environment == "territory_control":
        targets = observation.get("unclaimed_cells", []) + observation.get("opponent_territory", [])
        if not targets:
            return [0, 0]
        target = min(targets, key=lambda pos: abs(pos[0] - sx) + abs(pos[1] - sy))
        return move_towards(target)

    # For resource collection and default
    else:
        resources = observation.get("resources", [])
        if resources:
            target = min(resources, key=lambda pos: abs(pos[0] - sx) + abs(pos[1] - sy))
            return move_towards(target)
        else:
            # No resources: move randomly or towards opponent
            dx = 0
            dy = 0
            if ox != sx:
                dx = 1 if ox > sx else -1
            if oy != sy:
                dy = 1 if oy > sy else -1
            return [dx, dy]

